data = read('/input/data')
nodes = data['nodes']
edges = data['edges']
levels = {}
for node in nodes:
    levels = putmap(levels, node, 0)
changed = True
while changed:
    changed = False
    for edge in edges:
        u = edge['u']
        v = edge['v']
        candidate = get(levels, u, 0) + 1
        if candidate > get(levels, v, 0):
            levels = putmap(levels, v, candidate)
            changed = True
maximum = max([-1] + [get(levels, node, 0) for node in nodes])
layers = []
for level in range(maximum + 1):
    layer = [node for node in sorted(nodes) if get(levels, node, 0) == level]
    layers = layers + [layer]
result = {'main': layers}
